import type React from "react";
import { forwardRef, useId } from "react";

const AshIcon = forwardRef<SVGSVGElement, React.HTMLProps<SVGSVGElement>>(
  (props, ref) => {
    const id = useId();
    const patternId = `pattern-${id}`;
    const imageId = `image-${id}`;
    return (
      <svg
        aria-hidden="true"
        width="66"
        height="74"
        viewBox="0 0 66 74"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        xmlnsXlink="http://www.w3.org/1999/xlink"
        {...props}
        ref={ref}
      >
        <rect width="66" height="74" fill={`url(#${patternId})`} />
        <defs>
          <pattern
            id={patternId}
            patternContentUnits="objectBoundingBox"
            width="1"
            height="1"
          >
            <use
              xlinkHref={`#${imageId}`}
              transform="matrix(0.0142857 0 0 0.0128205 -1.37143 -0.0897436)"
            />
          </pattern>
          <image
            id={imageId}
            width="707"
            height="353"
            preserveAspectRatio="none"
            xlinkHref="data:image/png;base64,"
          />
        </defs>
      </svg>
    );
  },
);

AshIcon.displayName = "AshIcon";

export default AshIcon;
